import type { Cell, Row } from 'react-table';

import {
  getIsExcludableColumn,
  getIdOrStringAccessor,
} from './column-utils.js';
import { downloadCSV } from '../../core/utils/download.js';
import type {
  TableColumnAccessor,
  TableColumn,
  SingleColumn,
  ColumnGroup,
} from '../types/shared-table-types.js';

/**
 * Extracts the corresponding accessors and header names of all visible columns.
 *
 * @param columns - The column definitions
 * @param hiddenColumns - Columns that are currently not visible in the table
 *
 * @returns - The visible columns accessors along with the associated header names to write to the csv
 */
export function extractColumns(
  columns: TableColumn[],
  hiddenColumns: string[],
): {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  visibleColumns: (string | TableColumnAccessor<any>)[];
  headerNames: string[];
} {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const visibleColumns: (string | TableColumnAccessor<any>)[] = [];
  const headerNames: string[] = [];

  const getHeader = (column: SingleColumn, parentColumn?: ColumnGroup) => {
    // if accessor is a function, an id has to be defined
    const accessorOrId = getIdOrStringAccessor(column);

    const parentHeader = parentColumn ? parentColumn.header + '.' : '';
    const header =
      typeof column.header === 'string' ? column.header : accessorOrId;
    return parentHeader + header;
  };

  const addColumnIfPossible = (
    column: SingleColumn,
    parentColumn?: ColumnGroup,
  ) => {
    // if accessor is a function, an id has to be defined
    const idOrAccessor = getIdOrStringAccessor(column);

    if (
      column.accessor &&
      typeof idOrAccessor === 'string' &&
      !hiddenColumns.includes(idOrAccessor)
    ) {
      visibleColumns.push(column.accessor);
      headerNames.push(getHeader(column, parentColumn));
    }
  };

  columns.forEach((column) => {
    const singleColumn = column as SingleColumn;
    const columnGroup = column as ColumnGroup;
    // skip prefix and suffix columns
    const isExcludableColumn = column.id && getIsExcludableColumn(column.id);

    if (isExcludableColumn) {
      return;
    } else if (columnGroup.columns) {
      columnGroup.columns.forEach((subColumn: SingleColumn) =>
        addColumnIfPossible(subColumn, columnGroup),
      );
    } else {
      addColumnIfPossible(singleColumn);
    }
  });

  return { visibleColumns, headerNames };
}

/**
 * Generates a CSV string from a 2d array.
 *
 * @param dataRows - 2d array of table data rows
 * @returns - csv string
 */
export function convertArrayToCsv(dataRows: string[][]): string {
  let csv = '';
  for (const rowArray of dataRows) {
    let rowString = '';
    for (let i = 0; i < rowArray.length; i++) {
      const entry = rowArray[i];
      rowString += entry;
      if (i < rowArray.length - 1) {
        rowString += ',';
      }
    }
    csv += rowString + '\n';
  }
  return csv;
}

/**
 * Prepares the data for downloading the entire table.
 *
 * @param columns - The column definitions
 * @param hiddenColumns - Columns that are currently not visible in the table
 * @param data - The original table data
 */
export function prepareAllData(
  columns: TableColumn[],
  hiddenColumns: string[],
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  data: any[],
): string[][] {
  // retreive accessors and header names for all visibile columns from the column definition
  const { visibleColumns, headerNames } = extractColumns(
    columns,
    hiddenColumns,
  );
  const csvDataRows: string[][] = [headerNames];

  // retrieve values using the extracted column accessors
  data.forEach((entry, index) => {
    csvDataRows.push(
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      visibleColumns.map((columnAccessor: string | TableColumnAccessor<any>) =>
        getCellValue(columnAccessor, entry, index, data),
      ),
    );
  });

  return csvDataRows;
}

function getCellValue(
  columnAccessor: string | TableColumnAccessor<Record<string, unknown>>,
  entry: Record<string, unknown>,
  index: number,
  data: Record<string, unknown>[],
): string {
  let result: unknown = undefined;
  if (typeof columnAccessor === 'string') {
    result = columnAccessor.split('.').reduce((obj, key) => obj[key], entry);
  } else {
    result = columnAccessor(entry, index, {
      subRows: [], // we don't currently use subRows feature, so leave it empty
      data,
      depth: 0,
    });
  }

  if (typeof result === 'object') {
    result = getCustomCellValue(result);
  }

  return escapeForCSV(result);
}

/**
 * Gets custom cell value for use in download.
 * Checks if there is a custom toString() function and calls that.
 * Checks if there is a cellValue entry in the object and uses that
 * (if there is a cellType.type entry with value 'array' where
 * the elements are objects, then stringifies those objects).
 * Otherwise returns empty string for null values.
 * @param value - object containing cell data
 * @returns custom value or empty string.
 */
function getCustomCellValue(value: object | null): string | object {
  if (value === null) {
    return '';
  }
  // eslint-disable-next-line no-prototype-builtins
  else if (value.hasOwnProperty('toString')) {
    // if the object has a custom toString function then use that
    return value.toString();
  } else if (Array.isArray(value)) {
    // JSON.stringify is used to handle cases with nested objects in the array
    return JSON.stringify(value);
  } else {
    // Note: the `customValue` type below is specific to Notebooks and
    // can change in the future. The addition of this probably should not
    // have been approved in the pull request in July 2023 because it
    // is not a generic solution. For now fixing this bug issue (ADES-6576).
    // In future we will change/remove this TODO: ADES-6891
    // It will require a change on the Notebooks side too. They
    // should be able to put the code in a custom toString function.
    const customValue = value as {
      cellValue: unknown | unknown[];
      cellType?: { type: string };
    };
    if (customValue && 'cellValue' in customValue) {
      if (
        customValue.cellValue === undefined ||
        customValue.cellValue === null
      ) {
        return '';
      } else {
        if (
          customValue.cellType?.type === 'array' &&
          (customValue.cellValue as unknown[]).length > 0 &&
          typeof customValue.cellValue[0] === 'object'
        ) {
          // treat it as array of objects, and stringify each object
          return (customValue.cellValue as unknown[]).map((entry) =>
            JSON.stringify(entry),
          );
        }
        return customValue.cellValue;
      }
    }
  }
  return '';
}

/**
 * Extracts the data for downloading the current page.
 *
 * @param page - The current page rows.
 * @param selectedOnly - Only download selected rows of the current page.
 */
export function prepareCurrentPageData(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  page: Row<any>[],
  selectedOnly?: boolean,
): string[][] {
  const csvDataRows: string[][] = [];

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const getHeader = (cell: Cell<any>) => {
    const parentHeader = cell.column.parent
      ? cell.column.parent.Header?.toString() + '.'
      : '';
    const header = cell.column.Header?.toString() || '';

    return !getIsExcludableColumn(cell.column.id) ? parentHeader + header : [];
  };

  if (page.length > 0) {
    csvDataRows.push(page[0].cells.flatMap((cell) => getHeader(cell)));

    page.forEach((pageRow) => {
      if (!selectedOnly || pageRow.isSelected) {
        csvDataRows.push(
          pageRow.cells.flatMap((cell) =>
            !getIsExcludableColumn(cell.column.id)
              ? escapeForCSV(cell.value)
              : [],
          ),
        );
      }
    });
  }

  return csvDataRows;
}

/**
 * Escapes the string if the original value contains quotes or commas.
 * For CSV, to escape commas surround the whole string with double quotes and
 * to escape quotes in the string, prefix the quote with a quote. Arrays are
 * stringified and escaped. Undefined and null are converted to empty string.
 * Newlines are replaced with spaces.
 * @param original - original cell value
 *
 * @returns escaped cell value if necessary, otherwise the original one
 */
export function escapeForCSV(original: unknown): string {
  if (original === undefined || original === null) {
    return '';
  } else if (Array.isArray(original)) {
    return escapeForCSV(original.toString());
  } else if (typeof original === 'string') {
    const shouldEscape = original.includes('"') || original.includes(',');
    const result = shouldEscape
      ? '"' + original.replaceAll('"', '""') + '"'
      : original;
    return result.replaceAll('\n', ' ');
  }
  return original as string; // doesn't matter
}

/**
 * Downloads the entire table data, without the hidden columns.
 * If pagination is active, all pages are downloaded.
 *
 * @param columns - The column definitions
 * @param hiddenColumns - Columns that are currently not visible in the table
 * @param data - The original table data
 *
 * @internal
 */
export function _downloadAll(
  columns: TableColumn[],
  hiddenColumns: string[],
  data: any[], // eslint-disable-line @typescript-eslint/no-explicit-any
): void {
  const result = prepareAllData(columns, hiddenColumns, data);
  const csv = convertArrayToCsv(result);
  downloadCSV(csv, 'table-data.csv');
}

/**
 * Downloads the data from the current page.
 *
 * @param page - The current page rows
 * @param selectedOnly - Only download selected rows of the current page
 *
 * @internal
 */
export function _downloadCurrentPage(
  page: Row<any>[], // eslint-disable-line @typescript-eslint/no-explicit-any
  selectedOnly?: boolean,
): void {
  const result = prepareCurrentPageData(page, selectedOnly);
  const csv = convertArrayToCsv(result);
  downloadCSV(csv, 'table-data.csv');
}

/**
 * Checks if no rows are selected on the page.
 * @param page - current page
 *
 * @returns true if no rows are selected
 */
export function noRowsSelected(
  page: Row<any>[], // eslint-disable-line @typescript-eslint/no-explicit-any
): boolean {
  return page.every((pageRow) => {
    if (pageRow.isSelected) {
      return false;
    }
    return true;
  });
}
